ucl_unescape_json_string (char *str, size_t len)
{
        char *t = str, *h = str;
        int i, uval;

        if (len <= 1) {
                return len;
        }
        /* t is target (tortoise), h is source (hare) */

        while (len) {
                if (*h == '\\') {
                        h ++;

                        if (len == 1) {
                                /*
                                 * If \ is last, then do not try to go further
                                 * Issue: #74
                                 */
                                len --;
                                *t++ = '\\';
                                continue;
                        }

                        switch (*h) {
                        case 'n':
                                *t++ = '\n';
                                break;
                        case 'r':
                                *t++ = '\r';
                                break;
                        case 'b':
                                *t++ = '\b';
                                break;
                        case 't':
                                *t++ = '\t';
                                break;
                        case 'f':
                                *t++ = '\f';
                                break;
                        case '\\':
                                *t++ = '\\';
                                break;
                        case '"':
                                *t++ = '"';
                                break;
                        case 'u':
                                /* Unicode escape */
                                uval = 0;
                                h ++; /* u character */
                                len --;

                                if (len > 3) {
                                        for (i = 0; i < 4; i++) {
                                                uval <<= 4;
                                                if (isdigit (h[i])) {
                                                        uval += h[i] - '0';
                                                }
                                                else if (h[i] >= 'a' && h[i] <= 'f') {
                                                        uval += h[i] - 'a' + 10;
                                                }
                                                else if (h[i] >= 'A' && h[i] <= 'F') {
                                                        uval += h[i] - 'A' + 10;
                                                }
                                                else {
                                                        break;
                                                }
                                        }

                                        /* Encode */
                                        if(uval < 0x80) {
                                                t[0] = (char)uval;
                                                t ++;
                                        }
                                        else if(uval < 0x800) {
                                                t[0] = 0xC0 + ((uval & 0x7C0) >> 6);
                                                t[1] = 0x80 + ((uval & 0x03F));
                                                t += 2;
                                        }
                                        else if(uval < 0x10000) {
                                                t[0] = 0xE0 + ((uval & 0xF000) >> 12);
                                                t[1] = 0x80 + ((uval & 0x0FC0) >> 6);
                                                t[2] = 0x80 + ((uval & 0x003F));
                                                t += 3;
                                        }
